workflowScript:
const plan = await runs.run("plan", {
  agent: "feature-planner",
  task: "Plan the implementation, acceptance criteria, risks, and validation. Do not edit files."
});
const implementation = await runs.run("implementation", {
  agent: "worker-complex",
  task: "Implement the approved plan below as the sole writer in the workflow cwd. Commit before finishing so later validators inspect the same final tree.\n\n" + plan.output,
  acceptance: {
    level: "checked",
    evidence: ["changed-files", "commands-run", "validation-output", "residual-risks"]
  }
});
const validation = await runs.all([
  {
    key: "tests",
    agent: "tester-complex",
    task: "Read-only test verification of the implementation. Inspect and run relevant tests; do not edit files.\n\n" + implementation.output
  },
  {
    key: "review",
    agent: "reviewer-complex",
    task: "Read-only fresh review for correctness, regressions, and spec conformity.\n\n" + implementation.output
  }
]);
return {
  plan: plan.output,
  implementation: implementation.output,
  validation: validation.map((result) => ({ key: result.key, output: result.output }))
};
